INSERT INTO `dormitory_rule` VALUES (1,NULL,'宿舍管理公约','1. 遵守学校各项规章制度\n2. 保持宿舍卫生整洁\n3. 按时归宿，不得晚归\n4. 禁止使用大功率电器\n5. 禁止在宿舍饲养宠物\n6. 节约用水用电',1,'2026-02-13 19:19:59','2026-02-13 19:19:59'),(2,NULL,'违规处罚条例','1. 使用大功率电器者，没收电器并给予警告\n2. 卫生检查不合格者，连续3次取消评优资格\n3. 晚归超过3次者，给予通报批评\n4. 私自换寝者，取消当学期换寝资格',3,'2026-02-13 19:19:59','2026-02-13 19:19:59'),(3,NULL,'新公约','测试内容',1,'2026-02-13 20:07:04','2026-02-13 20:07:04'),(4,NULL,'新公约','测试内容',1,'2026-02-13 20:11:53','2026-02-13 20:11:53');
/*!40000 ALTER TABLE `dormitory_rule` ENABLE KEYS */;
