DROP TABLE IF EXISTS `student`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `student` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `student_number` varchar(20) NOT NULL COMMENT '学号',
  `password` varchar(100) NOT NULL COMMENT '密码(MD5加密)',
  `name` varchar(50) NOT NULL COMMENT '姓名',
  `gender` tinyint NOT NULL COMMENT '性别: 0-女, 1-男',
  `college` varchar(100) DEFAULT NULL COMMENT '学院',
  `major` varchar(100) DEFAULT NULL COMMENT '专业',
  `class_name` varchar(50) DEFAULT NULL COMMENT '班级',
  `phone` varchar(20) DEFAULT NULL COMMENT '联系电话',
  `avatar` varchar(1000) DEFAULT NULL COMMENT '头像URL',
  `building_id` bigint DEFAULT NULL COMMENT '当前所在楼栋ID',
  `room_id` bigint DEFAULT NULL COMMENT '当前所在宿舍ID',
  `bed_number` int DEFAULT NULL COMMENT '床位号',
  `status` tinyint DEFAULT '1' COMMENT '状态: 0-禁用, 1-正常',
  `create_time` datetime DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`),
  UNIQUE KEY `student_number` (`student_number`),
  KEY `idx_student_number` (`student_number`),
  KEY `idx_student_building` (`building_id`),
  KEY `idx_student_room` (`room_id`)
) ENGINE=InnoDB AUTO_INCREMENT=414 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='学生表';
