  `is_paid` tinyint DEFAULT '0' COMMENT '是否已支付: 0-未支付, 1-已支付',
  `pay_time` datetime DEFAULT NULL COMMENT '支付时间',
  `pay_method` varchar(20) DEFAULT NULL COMMENT '支付方式: wechat-微信, alipay-支付宝',
  `manager_id` bigint DEFAULT NULL COMMENT '录入人ID',
  `create_time` datetime DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_room_year_month` (`room_id`,`year`,`month`),
  KEY `idx_bill_room` (`room_id`),
  KEY `idx_bill_year_month` (`year`,`month`)
) ENGINE=InnoDB AUTO_INCREMENT=8 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='水电费账单表';
